const roadmapList = `-- name: RoadmapList :many
SELECT f.uuid,f.title,f.body,f.status,f.created_at,f.updated_at,'feature_request'::text AS source_type,''::text AS source_issue_url
FROM feature_requests f WHERE f.organization_id=$3 AND f.is_public AND f.status IN ('planned','in_progress','released')
UNION ALL
SELECT r.uuid,r.title,r.body,r.status,r.created_at,r.updated_at,'issue'::text AS source_type,r.source_issue_url
FROM roadmap_entries r WHERE r.organization_id=$3 AND (NOT $4::boolean OR r.is_public)
ORDER BY created_at DESC,uuid LIMIT $2 OFFSET $1
`

type RoadmapListParams struct {
	RowOffset      int32 `json:"row_offset"`
	RowLimit       int32 `json:"row_limit"`
	OrganizationID int64 `json:"organization_id"`
	PublicOnly     bool  `json:"public_only"`
}

type RoadmapListRow struct {
	Uuid           uuid.UUID          `json:"uuid"`
	Title          string             `json:"title"`
	Body           string             `json:"body"`
	Status         string             `json:"status"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	SourceType     string             `json:"source_type"`
	SourceIssueUrl string             `json:"source_issue_url"`
}

func (q *Queries) RoadmapList(ctx context.Context, arg RoadmapListParams) ([]RoadmapListRow, error) {
	rows, err := q.db.Query(ctx, roadmapList,
		arg.RowOffset,
		arg.RowLimit,
		arg.OrganizationID,
		arg.PublicOnly,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RoadmapListRow{}
	for rows.Next() {
		var i RoadmapListRow
		if err := rows.Scan(
			&i.Uuid,
			&i.Title,
			&i.Body,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SourceType,
			&i.SourceIssueUrl,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

